def spectral_norm(n: int, iterations: int) -> float:

    u: list[float] = []
    for i in range(n):
        u.append(1.0)
    v: list[float] = []
    for i in range(n):
        v.append(0.0)
    for it in range(iterations):
        v = mult_atv(mult_av(u))
        u = mult_atv(mult_av(v))
    vbv: float = 0.0
    vv: float = 0.0
    for i in range(n):
        vbv += u[i] * v[i]
        vv += v[i] * v[i]
    return (vbv / vv) ** 0.5


def mult_atv(v: list[float]) -> list[float]:

    n: int = len(v)
    out: list[float] = []
    for i in range(n):
        acc: float = 0.0
        for j in range(n):
            acc += v[j] / (((i + j) * (i + j + 1)) // 2 + j + 1)
        out.append(acc)
    return out


def mult_av(v: list[float]) -> list[float]:

    n: int = len(v)
    out: list[float] = []
    for i in range(n):
        acc: float = 0.0
        for j in range(n):
            acc += v[j] / (((i + j) * (i + j + 1)) // 2 + i + 1)
        out.append(acc)
    return out

